you can refer to this to user firecrawl request in n8n https://www.firecrawl.dev/blog/firecrawl-n8n-web-automation

for JSON output, in n8n - scroll to the JSON configuration section and switch from “Fixed” to “Expression” mode:

yeah, you can achieve this with /search. Use this sample body which uses the location parameter:

{
  "query": "property prices pincode 110001 Delhi",
  "limit": 10,
  "location": "IN",
  "scrapeOptions": {
    "formats": ["markdown", "json"],
    "onlyMainContent": true,
    "jsonOptions": {
      "schema": {
        "type": "object",
        "properties": {
          "prices": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "price": {"type": "string"},
                "location": {"type": "string"},
                "property_type": {"type": "string"},
                "area": {"type": "string"}
              }
            }
          }
        }
      },
      "prompt": "Extract all property prices, locations, and details from this page"
    },
    "headers": {
      "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
    }
  }
}
